compare.check:
(args, got) => {
    const w = args.args[0][0], n = w.length, total = w.reduce((a, b) => a + b, 0);
    if (!Array.isArray(got) || got.length !== args.ops.length || got[0] !== null) return false;
    const cnt = new Array(n).fill(0), m = got.length - 1;
    for (let i = 1; i < got.length; i++) {
      const x = got[i];
      if (!Number.isInteger(x) || x < 0 || x >= n) return false;
      cnt[x]++;
    }
    return cnt.every((c, i) => {
      const p = w[i] / total, mu = m * p, sd = Math.sqrt(m * p * (1 - p));
      return Math.abs(c - mu) <= 6 * sd + 4;
    });
  }
